	sections = {
		{
			title = "Resumen",
			text = [=[Witherfang es una gran araña que caza en los callejones de la capital en ruinas. Nunca caza sola. Un enjambre de sus crías la sigue por las calles, y todo lo que muerde queda envenenado. Los boticarios de {link:undercity}Entrañas{/link} han oído que su veneno puede corroer incluso la carne no muerta. Ese rumor asusta a la mayoría de los {link:forsaken}Renegados{/link}. A los boticarios les encanta, pues prefieren estudiar un veneno así antes que temerlo.]=],
		},
