})

Translate("esMX", "the-baron", {
	title = "El Barón",
	subtitle = "La abominación de la cabeza prestada",
	found = "El final de un pasillo en el sureste de las ruinas",
	hint = [=[Enfréntese a la gran abominación que guarda las salas del sureste de las ruinas.]=],
	allegiance = "Plaga",
	aliases = { "el Barón" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Barón es una enorme abominación que guarda una sala de la ciudad en ruinas. Golpea con grandes tajos y lanza lejos a sus enemigos. Le han arrancado la cabeza y se la han vuelto a coser tantas veces que apenas se sostiene. El maestro boticario {link:master-apothecary-faranell}Faranell{/link} conoce esa cabeza. Perteneció en otro tiempo a un gran mariscal de la {link:alliance}Alianza{/link}, un hombre al que {link:sylvanas-windrunner}la Dama Oscura{/link} mató con su propia mano.]=],
		},
		{
			title = "Importancia",
			text = [=[En la muerte, el gran mariscal se ha convertido en un monstruo en las ruinas del reino que un día vino a salvar. Los {link:forsaken}Renegados{/link} tienen planes para su cabeza. También los tiene un capitán de la {link:alliance}Alianza{/link} que espera a su señor en las ruinas.]=],
		},
	},
	mentions = {
		{ text = "Criaturas abominables" },
		{ text = "{link:the-writhing-haunt}Tormento{/link} sin fin" },
		{ text = "{link:the-writhing-haunt}Tormento{/link} sin fin" },
	},
	bonds = {
		{ id = "master-apothecary-faranell", name = "Maestro boticario Faranell", note = "conoce su cabeza" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "mató al hombre que fue" },
	},
})

Translate("esMX", "the-abandoned", {
	title = "El Abandonado",
	subtitle = "El frío de Market Street",
	found = "Market Street, en las ruinas",
	hint = [=[Enfréntese al que llega tras las oleadas de muertos en Market Street.]=],
	allegiance = "Plaga",
	sections = {
		{
			title = "Resumen",
			text = [=[El Abandonado es un lanzador de hechizos no muerto que ronda una vieja plaza de la capital en ruinas. No aparece enseguida. Primero los muertos se reúnen en oleadas alrededor de una estatua, y solo cuando han caído aparece él. Se envuelve en escarcha, atrapa a sus enemigos en hielo y les drena la vida para alimentar la suya. Lleva un cetro que los {link:forsaken}Renegados{/link} aprecian.]=],
		},
		{
			title = "Importancia",
			text = [=[El Abandonado es uno de los poderes que defienden las ruinas contra los {link:forsaken}Renegados{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica registra quién fue el Abandonado en vida, ni quién lo abandonó. Su nombre es todo lo que se sabe.]=],
		},
	},
})

Translate("esMX", "viktor-the-vile", {
