	sections = {
		{
			title = "Resumen",
			text = [=[Viktor el Vil es una bestia que se esconde en algún lugar de las ruinas de la capital, donde pocos pensarían en buscar. No sale por sí solo. Se dice que, si se aviva el viejo hogar de una casa en ruinas, los muertos llegan oleada tras oleada, y cuando se agotan, Viktor llega el último. Golpea con fuerza y no se cansa pronto, y quienes lo despiertan harían bien en estar preparados antes de encender el fuego.]=],
		},
		{
			title = "Importancia",
			text = [=[Viktor es el secreto de las ruinas. Muchos de los que cruzan la capital nunca llegan a encontrarlo.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica registra qué clase de bestia es Viktor ni quién le dio su nombre.]=],
		},
	},
})

Translate("esMX", "bjork", {
	title = "Bjork",
	subtitle = "El bruto de las ruinas",
	found = "Las ruinas del noroeste",
	hint = [=[Enfréntese al bruto no muerto que recorre las ruinas del noroeste.]=],
	allegiance = "Plaga",
	sections = {
		{
			title = "Resumen",
			text = [=[Bjork es un bruto no muerto que recorre las calles del noroeste de la capital en ruinas. Asesta golpes pesados que hacen retroceder incluso a guerreros con armadura, y cuando se vuelven hechizos contra él alza un escudo de magia oscura que los desvía. Los {link:forsaken}Renegados{/link} que luchan contra él aprenden a esperar a que el escudo se desvanezca y a mantener un muro firme a su espalda.]=],
		},
		{
			title = "Importancia",
			text = [=[Bjork es uno de los guardianes que la {link:scourge}Plaga{/link} dejó en las ruinas tras la caída de la ciudad.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica registra quién o qué fue Bjork antes de llegar a las ruinas. Ni siquiera su nombre tiene explicación.]=],
		},
	},
})

