Translate("esMX", "lordaeron-captain", {
	title = "Capitán de Lordaeron",
	subtitle = "Un capitán del reino caído",
	found = "Rara vez visto en las ruinas",
	hint = [=[Esté atento al capitán caído que rara vez se ve en las ruinas.]=],
	allegiance = "Lordaeron (caído)",
	sections = {
		{
			title = "Resumen",
			text = [=[A veces, en las ruinas de la capital, los muertos del ejército de {link:lordaeron}Lordaeron{/link} siguen firmes en sus puestos. Uno de ellos es un capitán del viejo reino. Rara vez se le ve, y nadie sabe cuándo aparecerá. Fuera cual fuera el juramento que un día lo ató a la ciudad, sigue en pie entre sus ruinas, mucho después de que desapareciera el reino al que sirvió.]=],
		},
		{
			title = "Importancia",
			text = [=[El capitán recuerda que los soldados de {link:lordaeron}Lordaeron{/link} cayeron defendiendo esta ciudad. Algunos todavía no se han detenido.]=],
		},
